from sqlalchemy.ext.asyncio import AsyncSessionfrom base.service import BaseServicefrom entities.container import Container, ContainerTypefrom helpers.search import Paginationfrom repositories.container import ContainerRepositoryfrom utils.container import ContainerSearchParamsclass ContainerService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)    async def search_container(            self, type_: ContainerType,            search: ContainerSearchParams,            pagination: Pagination    ) -> list[Container]:        containers = await self.repository.search(            type_=type_, **pagination.dict(), **search.dict()        )        return containers